#include <QMainWindow>

class QLabel;
class QSlider;
class QChart;
class QLineSeries;

// 探针窗口：验证 Qt Widgets + Qt Charts + 信号槽 + QSerialPort 链接是否可用。
class MainWindow : public QMainWindow {
    Q_OBJECT

public:
    explicit MainWindow(QWidget* parent = nullptr);

private slots:
    void onGainChanged(int value);

private:
    void buildUi();
    void refresh();

    QSlider* m_gainSlider = nullptr;
    QLabel* m_infoLabel = nullptr;
    QChart* m_chart = nullptr;
    QLineSeries* m_series = nullptr;
    double m_gain = 1.0;
};
"}

{"file_path": "C:\Users\ww\Documents\Codex\2026-10-09\ai\work\qt_probe\MainWindow.cpp", "content": "#include "MainWindow.h"

#include <QtCharts/QChart>
#include <QtCharts/QChartView>
#include <QtCharts/QLineSeries>
#include <QtCharts/QValueAxis>

#include <QSerialPort>
#include <QSerialPortInfo>

#include <QHBoxLayout>
#include <QLabel>
#include <QSlider>
#include <QVBoxLayout>
#include <QWidget>

#include <cmath>

MainWindow::MainWindow(QWidget* parent) : QMainWindow(parent) {
    setWindowTitle(QStringLiteral("环境探针 - Qt / Charts / SerialPort"));
    resize(900, 560);
    buildUi();
    refresh();
}

void MainWindow::buildUi() {
    auto* central = new QWidget(this);
    auto* outer = new QVBoxLayout(central);

    m_infoLabel = new QLabel(central);
    outer->addWidget(m_infoLabel);

    m_chart = new QChart();
    m_chart->setTitle(QStringLiteral("探针信号：LFM 实部（示例）"));
    m_series = new QLineSeries();
    m_chart->addSeries(m_series);

    auto* axisX = new QValueAxis();
    axisX->setTitleText(QStringLiteral("t (us)"));
    axisX->setRange(0.0, 10.0);
    auto* axisY = new QValueAxis();
    axisY->setTitleText(QStringLiteral("幅度"));
    axisY->setRange(-1.2, 1.2);

    m_chart->addAxis(axisX, Qt::AlignBottom);
    m_chart->addAxis(axisY, Qt::AlignLeft);
    m_series->attachAxis(axisX);
    m_series->attachAxis(axisY);
    m_chart->legend()->hide();

    auto* view = new QChartView(m_chart, central);
    view->setRenderHint(QPainter::Antialiasing);
    outer->addWidget(view, 1);

    auto* row = new QHBoxLayout();
    row->addWidget(new QLabel(QStringLiteral("增益"), central));
    m_gainSlider = new QSlider(Qt::Horizontal, central);
    m_gainSlider->setRange(1, 200);
    m_gainSlider->setValue(100);
    connect(m_gainSlider, &QSlider::valueChanged, this, &MainWindow::onGainChanged);
    row->addWidget(m_gainSlider, 1);
    outer->addLayout(row);

    setCentralWidget(central);
}

void MainWindow::onGainChanged(int value) {
    m_gain = value / 100.0;
    refresh();
}

void MainWindow::refresh() {
    // 模拟一段线性调频信号：s(t) = A * cos(2*pi*(f0*t + 0.5*k*t^2))
    const double f0 = 1.0e6;
    const double k = 2.0e11;
    const int n = 2000;
    const double tEnd = 10.0e-6;

    QList<QPointF> pts;
    pts.reserve(n);
    for (int i = 0; i < n; ++i) {
        const double t = tEnd * i / (n - 1);
        const double phase = 2.0 * M_PI * (f0 * t + 0.5 * k * t * t);
        pts.append(QPointF(t * 1e6, m_gain * std::cos(phase)));
    }
    m_series->replace(pts);

    const auto ports = QSerialPortInfo::availablePorts();
    m_infoLabel->setText(QStringLiteral("Qt %1 | 串口数量: %2 | 增益: %3")
                             .arg(QString::fromLatin1(qVersion()))
                             .arg(ports.size())
                             .arg(m_gain, 0, 'f', 2));
}
"}

