{"command": ""=== registry: WSL feature enabled? ==="
$k = 'HKLM:\SYSTEM\CurrentControlSet\Services\LxssManager'
if (Test-Path $k) { "LxssManager service key EXISTS"; (Get-ItemProperty $k).Start } else { "LxssManager service key MISSING" }
"=== Lxss registry (distros) ==="
if (Test-Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Lxss') { Get-ChildItem 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Lxss' | ForEach-Object { $p = Get-ItemProperty $_.PSPath; "{0} => {1}" -f $p.DistributionName, $p.BasePath } } else { "no Lxss distro registry" }
"=== try non-elevated ubuntu install (60s cap) ==="
$p = Start-Process -FilePath 'wsl.exe' -ArgumentList '--install','-d','Ubuntu','--no-launch' -PassThru -RedirectStandardOutput "$env:TEMP\wslout.txt" -RedirectStandardError "$env:TEMP\wslerr.txt" -ErrorAction SilentlyContinue
if ($p) {
  if ($p.WaitForExit(60000)) { "exit code: $($p.ExitCode)" } else { "still running after 60s"; Stop-Process -Id $p.Id -Force }
  "--- stdout ---"; Get-Content "$env:TEMP\wslout.txt" -ErrorAction SilentlyContinue | Select-Object -First 10
  "--- stderr ---"; Get-Content "$env:TEMP\wslerr.txt" -ErrorAction SilentlyContinue | Select-Object -First 10
}", "description": "Determine WSL feature state and try Ubuntu install", "timeoutMs": 120000}

