{"content": """"20λ 卡塞格伦天线：几何参数与经典设计公式。

坐标约定（全局统一，勿改）
--------------------------
* z 轴为天线视轴（boresight），+z 指向远场观察方向。
* 主反射面顶点位于 z = 0，抛物面方程  r^2 = 4*F*z。
* 主反射面焦点位于 z = F。
* 副反射面是双曲面；其「近焦点」与主反射面焦点重合。
* 所有长度单位默认以波长 λ 归一化（lam = 1.0）。

经典卡塞格伦设计关系（双曲面）
------------------------------
设主面焦距 F、副面放大率 M（= 系统等效焦距 / F）：

    L  = F / M             主面顶点到副面顶点的距离
    a  = L * (M - 1) / 2   双曲面实半轴
    e  = (M + 1) / (M - 1) 双曲面离心率
    c  = a * e             半焦距；近焦点在 z = L，远焦点在 z = -(2a - L)

近焦点必须落在 z = F 上，这是本模块 ``assert_consistency`` 校验的核心恒等式。
"""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np

__all__ = ["Cassegrain", "default_20lambda"]


@dataclass(frozen=True)
class Cassegrain:
    """卡塞格伦天线的几何参数（长度单位 = 波长）。"""

    lam: float = 1.0
    """工作波长（归一化单位）。"""

    D: float = 20.0
    """主反射面口径直径，单位 λ。题目给定 20λ。"""

    F: float = 8.0
    """主反射面焦距，单位 λ。焦径比 F/D = 0.4。"""

    M: float = 3.5
    """副面放大率。决定副面尺寸与遮挡比。"""

    d: float = 2.5
    """副反射面口径直径，单位 λ。"""

    @property
    def R(self) -> float:
        """主面口径半径。"""
        return 0.5 * self.D

    @property
    def Rs(self) -> float:
        """副面口径半径。"""
        return 0.5 * self.d

    @property
    def L(self) -> float:
        """主面顶点到副面顶点的轴向距离。"""
        return self.F / self.M

    @property
    def a(self) -> float:
        """双曲面实半轴。"""
        return self.L * (self.M - 1.0) / 2.0

    @property
    def e(self) -> float:
        """双曲面离心率。"""
        return (self.M + 1.0) / (self.M - 1.0)

    @property
    def c(self) -> float:
        """双曲面半焦距。"""
        return self.a * self.e

    @property
    def b2(self) -> float:
        """双曲面虚半轴平方 b^2 = c^2 - a^2。"""
        return self.c * self.c - self.a * self.a

    @property
    def z_vertex(self) -> float:
        """副面顶点 z 坐标。"""
        return self.L

    @property
    def z_focus_near(self) -> float:
        """副面近焦点 z 坐标（应等于主面焦距 F）。"""
        return self.L + 2.0 * self.c

    @property
    def z_focus_far(self) -> float:
        """副面远焦点 z 坐标（系统等效焦点，位于主面之后）。"""
        return self.L - 2.0 * self.c

    @property
    def z_rim_primary(self) -> float:
        """主面边缘的 z 坐标。"""
        return self.R * self.R / (4.0 * self.F)

    @property
    def blocking_ratio(self) -> float:
        """副面遮挡面积比（相对主面口径）。"""
        return (self.d / self.D) ** 2

    @property
    def system_focal_length(self) -> float:
        """系统等效焦距 M * F。"""
        return self.M * self.F

    def hyperbola_residual(self, z: float, r: float) -> float:
        """双曲面方程残差；= 0 表示点 (r, z) 在副面上。

        副面取靠近主面的那一叶： (z - L + a)^2 / a^2 - r^2 / b^2 = 1
        """
        return (z - self.z_vertex + self.a) ** 2 / self.a**2 - r * r / self.b2 - 1.0

    def assert_consistency(self, tol: float = 1e-9) -> None:
        """校验经典设计恒等式：副面近焦点必须与主面焦点重合。"""
        err = abs(self.z_focus_near - self.F)
        if err > tol * max(1.0, self.F):
            raise AssertionError(
                f"近焦点 z={self.z_focus_near:.6f} 与主面焦距 F={self.F:.6f} 不符，"
                f"误差 {err:.3e}"
            )
        if self.b2 <= 0.0:
            raise AssertionError(f"b^2={self.b2:.6f} 必须为正（需 M > 1）")
        if self.d >= self.D:
            raise AssertionError("副面口径必须小于主面口径")

    def summary(self) -> str:
        self.assert_consistency()
        lines = [
            "20λ 卡塞格伦天线几何参数",
            f"  波长 λ              = {self.lam:g}",
            f"  主面口径 D          = {self.D:g} λ   (半径 {self.R:g} λ)",
            f"  主面焦距 F          = {self.F:g} λ   (焦径比 F/D = {self.F / self.D:.3f})",
            f"  副面口径 d          = {self.d:g} λ   (半径 {self.Rs:g} λ)",
            f"  副面放大率 M        = {self.M:g}",
            f"  主面顶点-副面顶点 L = {self.L:.4f} λ",
            f"  双曲面实半轴 a      = {self.a:.4f} λ",
            f"  双曲面离心率 e      = {self.e:.4f}",
            f"  双曲面半焦距 c      = {self.c:.4f} λ",
            f"  副面顶点 z          = {self.z_vertex:.4f} λ",
            f"  近焦点 z            = {self.z_focus_near:.4f} λ  (= F ✓)",
            f"  远焦点 z            = {self.z_focus_far:.4f} λ",
            f"  主面边缘 z          = {self.z_rim_primary:.4f} λ",
            f"  系统等效焦距 M·F    = {self.system_focal_length:.4f} λ",
            f"  遮挡面积比          = {self.blocking_ratio * 100:.2f} %",
        ]
        return "\n".join(lines)


def default_20lambda() -> Cassegrain:
    """题目统一算例：20λ 卡塞格伦天线。"""
    return Cassegrain(lam=1.0, D=20.0, F=8.0, M=3.5, d=2.5)


if __name__ == "__main__":
    print(default_20lambda().summary())
