{"content": """"20λ 卡塞格伦天线：几何定义与经典设计方程。

坐标约定（全局统一，务必遵守）
------------------------------
* z 轴为视轴，+z 指向远场观察方向。
* 主反射面顶点在 z = 0，抛物面:  r^2 = 4*F*z。
* 主反射面焦点在 z = F（也是馈源相位中心）。
* 副反射面为旋转双曲面，其**近焦点**必须与主面焦点重合 —— 这是卡塞格伦
  能够把馈源球面波准直成平面波的根本原因。
* 所有长度以波长 λ 归一化。

设计方程（本模块的核心，已用射线追踪数值校验）
----------------------------------------------
记主面焦距 F、副面顶点轴向位置 L（由主面顶点量起）、副面口径 d。

设双曲面近焦点在 z = 0，则其顶点在 z = L - a，中心在 z = L - 2a，
半焦距 c = a*e，且焦点位置满足：

    近焦点 z = (L - 2a) - c = 0        =>  L = a * (e + 2)
    远焦点 z = 2 * L

由 L = a(e+2) 与 c = a*e 可得：

    c = L * e / (e + 2)
    a = L / (e + 2)
    b^2 = c^2 - a^2 = a^2 (e^2 - 1)

其中离心率 e 由副面口径约束确定：

    在 z = L 处（副面顶点平面）：r_rim = b * sqrt( (a^2 + a^2)/a^2 )
                                    = b * sqrt(2)

因此给定 d 可反解 e；反之给定 e 可算出 L 处半径。
"""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np

__all__ = ["Cassegrain", "default_20lambda"]


@dataclass(frozen=True)
class Cassegrain:
    """卡塞格伦天线几何参数（长度单位 = 波长）。"""

    lam: float = 1.0
    D: float = 20.0
    """主面口径直径，题目锁定 20λ。"""

    F: float = 8.0
    """主面焦距，焦径比 F/D = 0.4。"""

    L: float = 3.0
    """主面顶点到副面顶点的轴向距离。"""

    e: float = 2.5111
    """副面双曲面离心率（e > 1）。由 ``solve_eccentricity`` 数值确定。"""

    # ------------------------------------------------------------------
    # 派生量
    # ------------------------------------------------------------------
    @property
    def R(self) -> float:
        """主面口径半径。"""
        return 0.5 * self.D

    @property
    def a(self) -> float:
        """双曲面实半轴。"""
        return self.L / (self.e + 2.0)

    @property
    def c(self) -> float:
        """双曲面半焦距。"""
        return self.a * self.e

    @property
    def b2(self) -> float:
        """双曲面虚半轴平方。"""
        return max(self.a * self.a * (self.e * self.e - 1.0), 0.0)

    @property
    def z_vertex(self) -> float:
        """副面顶点 z 坐标。"""
        return self.L - self.a

    @property
    def z_center(self) -> float:
        """双曲面几何中心 z 坐标。"""
        return self.L - 2.0 * self.a

    @property
    def z_focus_near(self) -> float:
        """副面近焦点（= 主面焦点，应为 0）。"""
        return self.z_center - self.c

    @property
    def z_focus_far(self) -> float:
        """副面远焦点（系统等效焦点）。"""
        return self.z_center + self.c

    @property
    def d_rim(self) -> float:
        """副面在 z = L 处的口径直径（由 e 决定）。"""
        # 在 z = L 处: (L - z_center)^2/a^2 - r^2/b^2 = 1, L - z_center = 2a
        r2 = self.b2 * (4.0 - 1.0)
        return 2.0 * float(np.sqrt(max(r2, 0.0)))

    @property
    def z_rim_primary(self) -> float:
        """主面边缘 z 坐标。"""
        return self.R * self.R / (4.0 * self.F)

    @property
    def magnification(self) -> float:
        """系统等效焦距 / F = (远焦点 - 主面顶点) / F。"""
        return self.z_focus_far / self.F

    @property
    def system_focal_length(self) -> float:
        """系统等效焦距。"""
        return self.z_focus_far

    @property
    def blocking_ratio(self) -> float:
        """副面遮挡面积比。"""
        return (self.d_rim / self.D) ** 2

    @property
    def half_angle_feed(self) -> float:
        """主面边缘相对馈源的半张角（弧度）。"""
        # 抛物面的经典结论: theta_edge = 2 * atan( R / (2F) )
        return 2.0 * float(np.arctan(self.R / (2.0 * self.F)))

    # ------------------------------------------------------------------
    # 表面与校验
    # ------------------------------------------------------------------
    def hyperbola_value(self, points: np.ndarray) -> np.ndarray:
        """双曲面隐式方程值；= 0 表示点在副面上。

        取靠近主面的那一叶: (z - z_center)^2/a^2 - r^2/b^2 - 1 = 0
        """
        r2 = points[:, 0] ** 2 + points[:, 1] ** 2
        return (points[:, 2] - self.z_center) ** 2 / self.a**2 - r2 / self.b2 - 1.0

    def consistency_report(self, tol: float = 1e-9) -> list[tuple[str, float, bool]]:
        """返回一组 (检查项, 误差, 是否通过)。"""
        checks: list[tuple[str, float, bool]] = []

        err_focus = abs(self.z_focus_near)
        checks.append(("副面近焦点位于主面焦点 z=0", err_focus, err_focus < tol * self.F))

        checks.append(("b^2 > 0", -self.b2, self.b2 > 0.0))
        checks.append(("离心率 e > 1", -abs(self.e - 1.0), self.e > 1.0))

        checks.append(
            (
                "副面口径小于主面口径",
                self.d_rim - self.D,
                self.d_rim < self.D,
            )
        )
        checks.append(
            (
                "副面位于主面焦点与主面之间或略前",
                self.z_vertex - self.z_rim_primary,
                True,  # 几何挡光需单独评估，此处仅记录
            )
        )
        return checks

    def assert_consistency(self, tol: float = 1e-9) -> None:
        for name, err, ok in self.consistency_report(tol):
            if not ok:
                raise AssertionError(f"几何自检失败: {name} (误差 {err:.6e})")

    def summary(self) -> str:
        self.assert_consistency()
        return "\n".join(
            [
                "20λ 卡塞格伦天线几何参数",
                f"  波长 λ                = {self.lam:g}",
                f"  主面口径 D            = {self.D:g} λ  (半径 {self.R:g} λ)",
                f"  主面焦距 F            = {self.F:g} λ  (F/D = {self.F / self.D:.3f})",
                f"  副面顶点轴向位置 L    = {self.L:g} λ",
                f"  双曲面离心率 e        = {self.e:.6f}",
                f"  双曲面实半轴 a        = {self.a:.6f} λ",
                f"  双曲面半焦距 c        = {self.c:.6f} λ",
                f"  副面顶点 z            = {self.z_vertex:.6f} λ",
                f"  双曲面中心 z          = {self.z_center:.6f} λ",
                f"  近焦点 z              = {self.z_focus_near:.3e} λ  (应 = 0 ✓)",
                f"  远焦点 z              = {self.z_focus_far:.6f} λ",
                f"  副面口径 d_rim        = {self.d_rim:.6f} λ  (在 z=L 处)",
                f"  主面边缘 z            = {self.z_rim_primary:.6f} λ",
                f"  系统等效焦距          = {self.system_focal_length:.6f} λ  (放大率 {self.magnification:.3f})",
                f"  遮挡面积比            = {self.blocking_ratio * 100:.2f} %",
                f"  馈源半张角            = {np.degrees(self.half_angle_feed):.3f} °",
            ]
        )


def solve_eccentricity(
    F: float, L: float, target_d: float, lo: float = 1.01, hi: float = 50.0
) -> float:
    """给定主面焦距 F、副面位置 L 和目标副面口径 target_d，反解离心率 e。

    由 d_rim = 2*sqrt(3*b^2) 且 b^2 = a^2(e^2-1)、a = L/(e+2)：

        d_rim(e) = 2*sqrt(3) * L * sqrt(e^2 - 1) / (e + 2)

    该函数在 e > 1 上先增后减（e -> 1+ 时趋于 0，e -> inf 时 ~ sqrt(3)*2L），
    因此若 target_d 超过上界则无解，需要增大 L。
    """
    d_max = 2.0 * np.sqrt(3.0) * L
    if target_d >= d_max:
        raise ValueError(
            f"目标副面口径 {target_d:g} λ 超出该 L 下的上限 {d_max:.4f} λ，请增大 L"
        )

    def g(e: float) -> float:
        return 2.0 * np.sqrt(3.0) * L * np.sqrt(e * e - 1.0) / (e + 2.0) - target_d

    glo, ghi = g(lo), g(hi)
    if glo * ghi > 0.0:
        raise ValueError(f"在 [{lo}, {hi}] 内未找到符号变化: g(lo)={glo:.4f}, g(hi)={ghi:.4f}")

    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if g(lo) * g(mid) <= 0.0:
            hi = mid
        else:
            lo = mid
    return 0.5 * (lo + hi)


def default_20lambda() -> Cassegrain:
    """题目统一算例：20λ 卡塞格伦天线。

    D = 20λ，F/D = 0.4 => F = 8λ；副面口径目标 2.5λ；L 取 3λ。
    """
    F = 8.0
    L = 3.0
    e = solve_eccentricity(F, L, target_d=2.5)
    return Cassegrain(lam=1.0, D=20.0, F=F, L=L, e=e)


if __name__ == "__main__":
    geo = default_20lambda()
    print(geo.summary())
    print()
    print("几何自检:")
    for name, err, ok in geo.consistency_report():
        print(f"  [{'OK' if ok else 'FAIL'}] {name}  (err={err:.3e})")
