    # 表面与校验
    # ------------------------------------------------------------------
    def hyperbola_value(self, points: np.ndarray) -> np.ndarray:
        """双曲面隐式方程值；= 0 表示点在副面上。

        取靠近主面的那一叶: (z - z_center)^2/a^2 - r^2/b^2 - 1 = 0
        """
        r2 = points[:, 0] ** 2 + points[:, 1] ** 2
        return (points[:, 2] - self.z_center) ** 2 / self.a**2 - r2 / self.b2 - 1.0

    def consistency_report(self, tol: float = 1e-9) -> list[tuple[str, float, bool]]:
        """返回一组 (检查项, 误差, 是否通过)。"""
        checks: list[tuple[str, float, bool]] = []

        err_focus = abs(self.z_focus_near)
        checks.append(("副面近焦点位于主面焦点 z=0", err_focus, err_focus < tol * self.F))

        checks.append(("b^2 > 0", -self.b2, self.b2 > 0.0))
        checks.append(("离心率 e > 1", -abs(self.e - 1.0), self.e > 1.0))

        checks.append(
            (
                "副面口径小于主面口径",
                self.d_rim - self.D,
                self.d_rim < self.D,
            )
        )
        checks.append(
            (
                "副面位于主面焦点与主面之间或略前",
                self.z_vertex - self.z_rim_primary,
                True,  # 几何挡光需单独评估，此处仅记录
            )
        )
        return checks

    def assert_consistency(self, tol: float = 1e-9) -> None:
        for name, err, ok in self.consistency_report(tol):
            if not ok:
                raise AssertionError(f"几何自检失败: {name} (误差 {err:.6e})")

    def summary(self) -> str:
        self.assert_consistency()
        return "\n".join(
            [
                "20λ 卡塞格伦天线几何参数",
                f"  波长 λ                = {self.lam:g}",
                f"  主面口径 D            = {self.D:g} λ  (半径 {self.R:g} λ)",
                f"  主面焦距 F            = {self.F:g} λ  (F/D = {self.F / self.D:.3f})",
                f"  副面顶点轴向位置 L    = {self.L:g} λ",
                f"  双曲面离心率 e        = {self.e:.6f}",
                f"  双曲面实半轴 a        = {self.a:.6f} λ",
                f"  双曲面半焦距 c        = {self.c:.6f} λ",
                f"  副面顶点 z            = {self.z_vertex:.6f} λ",
                f"  双曲面中心 z          = {self.z_center:.6f} λ",
                f"  近焦点 z              = {self.z_focus_near:.3e} λ  (应 = 0 ✓)",
                f"  远焦点 z              = {self.z_focus_far:.6f} λ",
                f"  副面口径 d_rim        = {self.d_rim:.6f} λ  (在 z=L 处)",
                f"  主面边缘 z            = {self.z_rim_primary:.6f} λ",
                f"  系统等效焦距          = {self.system_focal_length:.6f} λ  (放大率 {self.magnification:.3f})",
                f"  遮挡面积比            = {self.blocking_ratio * 100:.2f} %",
                f"  馈源半张角            = {np.degrees(self.half_angle_feed):.3f} °",
            ]
        )


def solve_eccentricity(
    F: float, L: float, target_d: float, lo: float = 1.01, hi: float = 50.0
) -> float:
    """给定主面焦距 F、副面位置 L 和目标副面口径 target_d，反解离心率 e。

    由 d_rim = 2*sqrt(3*b^2) 且 b^2 = a^2(e^2-1)、a = L/(e+2)：

        d_rim(e) = 2*sqrt(3) * L * sqrt(e^2 - 1) / (e + 2)

    该函数在 e > 1 上先增后减（e -> 1+ 时趋于 0，e -> inf 时 ~ sqrt(3)*2L），
    因此若 target_d 超过上界则无解，需要增大 L。
    """
    d_max = 2.0 * np.sqrt(3.0) * L
    if target_d >= d_max:
        raise ValueError(
            f"目标副面口径 {target_d:g} λ 超出该 L 下的上限 {d_max:.4f} λ，请增大 L"
        )

    def g(e: float) -> float:
        return 2.0 * np.sqrt(3.0) * L * np.sqrt(e * e - 1.0) / (e + 2.0) - target_d

    glo, ghi = g(lo), g(hi)
    if glo * ghi > 0.0:
        raise ValueError(f"在 [{lo}, {hi}] 内未找到符号变化: g(lo)={glo:.4f}, g(hi)={ghi:.4f}")

    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if g(lo) * g(mid) <= 0.0:
            hi = mid
        else:
            lo = mid
    return 0.5 * (lo + hi)


def default_20lambda() -> Cassegrain:
    """题目统一算例：20λ 卡塞格伦天线。

    D = 20λ，F/D = 0.4 => F = 8λ；副面口径目标 2.5λ；L 取 3λ。
    """
    F = 8.0
    L = 3.0
    e = solve_eccentricity(F, L, target_d=2.5)
    return Cassegrain(lam=1.0, D=20.0, F=F, L=L, e=e)


if __name__ == "__main__":
    geo = default_20lambda()
    print(geo.summary())
    print()
    print("几何自检:")
    for name, err, ok in geo.consistency_report():
        print(f"  [{'OK' if ok else 'FAIL'}] {name}  (err={err:.3e})")
