            ]
        )


def solve_eccentricity(
    F: float, L: float, target_d: float, lo: float = 1.01, hi: float = 50.0
) -> float:
    """给定主面焦距 F、副面位置 L 和目标副面口径 target_d，反解离心率 e。

    由 d_rim = 2*sqrt(3*b^2) 且 b^2 = a^2(e^2-1)、a = L/(e+2)：

        d_rim(e) = 2*sqrt(3) * L * sqrt(e^2 - 1) / (e + 2)

    该函数在 e > 1 上先增后减（e -> 1+ 时趋于 0，e -> inf 时 ~ sqrt(3)*2L），
    因此若 target_d 超过上界则无解，需要增大 L。
    """
    d_max = 2.0 * np.sqrt(3.0) * L
    if target_d >= d_max:
        raise ValueError(
            f"目标副面口径 {target_d:g} λ 超出该 L 下的上限 {d_max:.4f} λ，请增大 L"
        )

    def g(e: float) -> float:
        return 2.0 * np.sqrt(3.0) * L * np.sqrt(e * e - 1.0) / (e + 2.0) - target_d

    glo, ghi = g(lo), g(hi)
    if glo * ghi > 0.0:
        raise ValueError(f"在 [{lo}, {hi}] 内未找到符号变化: g(lo)={glo:.4f}, g(hi)={ghi:.4f}")

    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if g(lo) * g(mid) <= 0.0:
            hi = mid
        else:
            lo = mid
    return 0.5 * (lo + hi)


def default_20lambda() -> Cassegrain:
    """题目统一算例：20λ 卡塞格伦天线。

    D = 20λ，F/D = 0.4 => F = 8λ；副面口径目标 2.5λ；L 取 3λ。
    """
    F = 8.0
    L = 3.0
    e = solve_eccentricity(F, L, target_d=2.5)
    return Cassegrain(lam=1.0, D=20.0, F=F, L=L, e=e)


if __name__ == "__main__":
    geo = default_20lambda()
    print(geo.summary())
    print()
    print("几何自检:")
    for name, err, ok in geo.consistency_report():
        print(f"  [{'OK' if ok else 'FAIL'}] {name}  (err={err:.3e})")

