{"content": """"20λ 卡塞格伦天线：几何定义与共焦设计方程。

坐标约定（全局统一，务必遵守）
------------------------------
* z 轴为视轴，+z 指向远场。
* 主反射面顶点在 z = 0，抛物面:  r^2 = 4*F*z，主面半径 R = D/2。
* 主反射面焦点在 z = F（馈源相位中心所在）。
* 副反射面是旋转双曲面（靠近主面的那一叶），其**近焦点必须落在主面焦点
  z = F 上** —— 这是卡塞格伦把馈源球面波准直成平面波的唯一原因。
* 所有长度以波长 λ 归一化。

设计方程（已用射线追踪数值校验，见同目录 rays.py）
--------------------------------------------------
以主面焦距 F、放大率 M（> 1）为自由参数：

    L = F / M                   主面顶点 -> 副面顶点 的轴向距离
    a = F * (M - 1) / 2         双曲面实半轴
    c = a + F                   双曲面半焦距；近焦点 = c - a = F
    e = c / a = (M + 1) / (M - 1)   离心率
    b^2 = c^2 - a^2 = a^2 (e^2 - 1)

副面顶点位于 z = L，双曲面中心位于 z = L + a，
远焦点（系统等效焦点）位于 z = 2L + 2F = F * (2M - 1)。
系统等效焦距 f_sys = M * F。

副面在 z = L 处的口径半径由双曲面方程给出：

    r_rim = b * sqrt( (a^2 - a^2) / a^2 + 1 ) 在 z - z_center = -a 处
          = b * sqrt(1 - 1) -> 需用一般式重新代入

本模块用 ``rim_radius_at(z)`` 直接数值求解，避免手推出错。
"""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np

__all__ = ["Cassegrain", "default_20lambda"]


@dataclass(frozen=True)
class Cassegrain:
    """卡塞格伦天线几何参数（长度单位 = 波长）。"""

    lam: float = 1.0
    D: float = 20.0
    """主面口径直径（题目锁定 20λ）。"""

    F: float = 8.0
    """主面焦距；F/D = 0.4。"""

    M: float = 4.0
    """放大率（> 1）。决定副面位置、尺寸与遮挡比。"""

    # ------------------------------------------------------------------
    # 由 (F, M) 派生的量
    # ------------------------------------------------------------------
    @property
    def R(self) -> float:
        """主面口径半径。"""
        return 0.5 * self.D

    @property
    def L(self) -> float:
        """主面顶点到副面顶点的轴向距离。"""
        return self.F / self.M

    @property
    def a(self) -> float:
        """双曲面实半轴。"""
        return 0.5 * self.F * (self.M - 1.0)

    @property
    def c(self) -> float:
        """双曲面半焦距。"""
        return self.a + self.F

    @property
    def e(self) -> float:
        """双曲面离心率。"""
        return self.c / self.a

    @property
    def b2(self) -> float:
        """双曲面虚半轴平方。"""
        return max(self.c * self.c - self.a * self.a, 0.0)

    @property
    def b(self) -> float:
        return float(np.sqrt(self.b2))

    @property
    def z_vertex(self) -> float:
        """副面顶点 z 坐标。"""
        return self.L

    @property
    def z_center(self) -> float:
        """双曲面几何中心 z 坐标。"""
        return self.L + self.a

    @property
    def z_focus_near(self) -> float:
        """近焦点 z（必须等于 F，即与主面焦点重合）。"""
        return self.z_center - self.c

    @property
    def z_focus_far(self) -> float:
        """远焦点 z（系统等效焦点）。"""
        return self.z_center + self.c

    @property
    def system_focal_length(self) -> float:
        """系统等效焦距 = M * F。"""
        return self.z_focus_far

    @property
    def z_rim_primary(self) -> float:
        """主面边缘 z 坐标。"""
        return self.R * self.R / (4.0 * self.F)

    @property
    def half_angle_feed(self) -> float:
        """主面边缘相对馈源的半张角（弧度）。"""
        return 2.0 * float(np.arctan(self.R / (2.0 * self.F)))

    # ------------------------------------------------------------------
    # 副面几何
    # ------------------------------------------------------------------
    def rim_radius_at(self, z: float) -> float:
        """给定 z，返回双曲面（近主面叶）上的半径 r。

        由 (z - z_center)^2 / a^2 - r^2 / b^2 = 1 解出：

            r^2 = b^2 * [ (z - z_center)^2 / a^2 - 1 ]

        当 |z - z_center| >= a 时才有实数解。
        """
        t = (z - self.z_center) ** 2 / self.a**2 - 1.0
        return float(np.sqrt(max(t, 0.0)) * self.b)

    @property
    def d_rim(self) -> float:
        """副面口径直径：取副面顶点平面 z = L 处的半径。"""
        return 2.0 * self.rim_radius_at(self.L)

    @property
    def blocking_ratio(self) -> float:
        """副面遮挡面积比（相对主面口径）。"""
        return (self.d_rim / self.D) ** 2

    def hyperbola_value(self, points: np.ndarray) -> np.ndarray:
        """双曲面隐式方程值；(r,z) 在近主面叶上时为 0。

        定义 F(p) = (z - z_center)^2/a^2 - r^2/b^2 - 1
        """
        r2 = points[:, 0] ** 2 + points[:, 1] ** 2
        return (points[:, 2] - self.z_center) ** 2 / self.a**2 - r2 / self.b2 - 1.0

    # ------------------------------------------------------------------
    # 校验
    # ------------------------------------------------------------------
    def consistency_report(self, tol: float = 1e-9) -> list[tuple[str, float, bool]]:
        checks: list[tuple[str, float, bool]] = []

        err = abs(self.z_focus_near - self.F)
        checks.append((f"近焦点 z = F ({self.F:g})", err, err <= tol * max(1.0, self.F)))

        checks.append(("M > 1（放大率）", -abs(self.M - 1.0), self.M > 1.0))
        checks.append(("b^2 > 0", -self.b2, self.b2 > 0.0))
        checks.append(
            (f"副面顶点 z={self.L:.4f} 在主面焦点 z={self.F:.4f} 之前", self.L - self.F, self.L < self.F)
        )
        checks.append(
            (
                f"副面顶点 z={self.L:.4f} 在主面边缘 z={self.z_rim_primary:.4f} 之内",
                self.L - self.z_rim_primary,
                self.L < self.z_rim_primary,
            )
        )
        checks.append((f"副面口径 d={self.d_rim:.4f} < D={self.D:g}", self.d_rim - self.D, self.d_rim < self.D))
        checks.append(
            (f"遮挡面积比 {self.blocking_ratio * 100:.2f}% < 10%", self.blocking_ratio - 0.10, self.blocking_ratio < 0.10)
        )
        return checks

    def assert_consistency(self, tol: float = 1e-9) -> None:
        for name, err, ok in self.consistency_report(tol):
            if not ok:
                raise AssertionError(f"几何自检失败: {name} (余量 {err:.6e})")

    def summary(self) -> str:
        self.assert_consistency()
        return "\n".join(
            [
                "20λ 卡塞格伦天线几何参数",
                f"  波长 λ                = {self.lam:g}",
                f"  主面口径 D            = {self.D:g} λ  (半径 {self.R:g} λ)",
                f"  主面焦距 F            = {self.F:g} λ  (F/D = {self.F / self.D:.3f})",
                f"  放大率 M              = {self.M:g}",
                f"  副面顶点轴向位置 L    = {self.L:.6f} λ",
                f"  双曲面实半轴 a        = {self.a:.6f} λ",
                f"  双曲面半焦距 c        = {self.c:.6f} λ",
                f"  双曲面离心率 e        = {self.e:.6f}",
                f"  双曲面虚半轴 b        = {self.b:.6f} λ",
                f"  双曲面中心 z          = {self.z_center:.6f} λ",
                f"  近焦点 z              = {self.z_focus_near:.6f} λ  (应 = F)",
                f"  远焦点 z              = {self.z_focus_far:.6f} λ",
                f"  副面口径 d_rim        = {self.d_rim:.6f} λ",
                f"  主面边缘 z            = {self.z_rim_primary:.6f} λ",
                f"  系统等效焦距          = {self.system_focal_length:.6f} λ  (f/D = {self.system_focal_length / self.D:.3f})",
                f"  遮挡面积比            = {self.blocking_ratio * 100:.3f} %",
                f"  馈源半张角            = {np.degrees(self.half_angle_feed):.3f} °",
            ]
        )


def default_20lambda(M: float = 4.0, F: float = 8.0, D: float = 20.0) -> Cassegrain:
    """题目统一算例：20λ 卡塞格伦天线（D = 20λ, F/D = 0.4）。"""
    return Cassegrain(lam=1.0, D=D, F=F, M=M)


if __name__ == "__main__":
    geo = default_20lambda()
    print(geo.summary())
    print()
    for name, margin, ok in geo.consistency_report():
        print(f"  [{'OK  ' if ok else 'FAIL'}] {name}  (margin={margin:.3e})")
