def _reflect(d: np.ndarray, n: np.ndarray) -> np.ndarray:
    """矢量反射 d' = d - 2 (d.n) n，返回单位矢量。d、n 形状 (N,3)。"""
    dn = np.sum(d * n, axis=1, keepdims=True)
    out = d - 2.0 * dn * n
    return out / np.linalg.norm(out, axis=1, keepdims=True)

